/**
 * Within-trial encoding-sequence sampler — design §8.1.
 *
 * Each dual-task trial has 4 memory items (M) and 4 imagery probes / stars
 * (S), arranged as a length-8 string over {M, S}. The design constraint is
 * **run-length ≤ 2** (no three M's or three S's in a row), with first and
 * last positions free. Brute-force enumeration over all 2^8 binary strings
 * (filtered to 4M+4S and run-length ≤ 2) yields **34** valid strings.
 * Note: the design doc §8.1 originally claimed 38; that was a miscount.
 * See BUILD_LOG step 5 for the corrected combinatorial derivation.
 *
 * Single-task trials (D-only, T-only, I-only) reuse the same 34-string pool,
 * with the unused-modality slots filled by open-square dummies — so single-
 * and dual-task trials have an identical temporal envelope (design §8.2).
 *
 * For arbitrary block sizes, the sampler uses sample-without-replacement:
 * it draws each of the 34 sequences exactly once, then re-shuffles. For the
 * 24-trial main-condition blocks, however, we tighten this further and draw
 * a UNIQUE 24-sequence subset whose slot-position totals are exactly
 * balanced: each of the 8 positions hosts M on 12 trials and S on 12 trials.
 * This keeps the five condition types aligned not only in admissible
 * sequencing but also in the temporal distribution of memory-vs-star
 * positions across the full 24-trial comparison set.
 */
import { getSessionPRNG } from '../prng.js';
import { config } from '../config.js';

const SEQUENCE_LENGTH = 8;
const M_COUNT = 4;
const S_COUNT = 4;

let CACHED_VALID = null;

/**
 * Returns the full enumeration of valid length-8 sequences as an array of
 * arrays (each inner array length 8, entries 'M' or 'S'). Built once and
 * memoised. Sequence order is canonical (sorted as binary strings) so the
 * enumeration is deterministic across runs and tests can rely on the order.
 */
export function enumerateValidSequences() {
  if (CACHED_VALID !== null) return CACHED_VALID;
  const cap = config.sequencing.within_trial_run_length_cap;
  const out = [];

  for (let mask = 0; mask < 1 << SEQUENCE_LENGTH; mask++) {
    const seq = [];
    let ones = 0;
    for (let bit = SEQUENCE_LENGTH - 1; bit >= 0; bit--) {
      const b = (mask >> bit) & 1;
      seq.push(b === 1 ? 'M' : 'S');
      ones += b;
    }
    if (ones !== M_COUNT) continue;
    if (!withinRunLengthCap(seq, cap)) continue;
    out.push(Object.freeze(seq));
  }

  CACHED_VALID = Object.freeze(out);
  return CACHED_VALID;
}

export function withinRunLengthCap(seq, cap) {
  let runChar = null;
  let runLen = 0;
  for (const c of seq) {
    if (c === runChar) {
      runLen += 1;
      if (runLen > cap) return false;
    } else {
      runChar = c;
      runLen = 1;
    }
  }
  return true;
}

/**
 * Stateful sample-without-replacement pool. Calling next() returns a single
 * sequence (a frozen array). When the underlying shuffled list is exhausted,
 * a new one is shuffled in place and sampling continues. The pool is keyed
 * by `label` so D-only, T-only, I-only, I+D, I+T can each maintain their own
 * independent draw history (avoids one condition's random walk biasing
 * another's, which would matter if conditions were drawn from the same pool
 * with run-length constraints).
 */
const POOLS = new Map();

export function createSequencePool(label, prng = getSessionPRNG()) {
  if (POOLS.has(label)) return POOLS.get(label);
  const valid = enumerateValidSequences();
  const state = {
    label,
    prng,
    queue: prng.shuffle(valid.slice()),
    cursor: 0,
    drawn_count: 0,
    next() {
      if (state.cursor >= state.queue.length) {
        state.queue = state.prng.shuffle(valid.slice());
        state.cursor = 0;
      }
      const seq = state.queue[state.cursor++];
      state.drawn_count += 1;
      return seq;
    },
  };
  POOLS.set(label, state);
  return state;
}

export function resetSequencePools() {
  POOLS.clear();
}

function hasExactSlotBalance(sequences) {
  const target = sequences.length / 2;
  if (!Number.isInteger(target)) return false;
  for (let pos = 0; pos < SEQUENCE_LENGTH; pos++) {
    let mCount = 0;
    for (const seq of sequences) {
      if (seq[pos] === 'M') mCount++;
    }
    if (mCount !== target) return false;
  }
  return true;
}

function drawExactlyBalancedUniqueBlock(blockSize, prng, maxAttempts) {
  const valid = enumerateValidSequences();
  if (blockSize > valid.length) {
    throw new Error(
      `drawBlockSequences: cannot draw ${blockSize} unique sequences from a ${valid.length}-sequence pool.`
    );
  }
  if (blockSize % 2 !== 0) {
    throw new Error(
      `drawBlockSequences: exact slot-position balance requires an even block size, got ${blockSize}.`
    );
  }

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const candidate = prng.shuffle(valid.slice()).slice(0, blockSize);
    if (hasExactSlotBalance(candidate)) return Object.freeze(candidate.slice());
  }

  throw new Error(
    `drawBlockSequences: failed to find a ${blockSize}-trial unique sequence set with exact slot-position balance after ${maxAttempts} attempts.`
  );
}

/**
 * Draw a block's worth of within-trial M/S sequences.
 *
 * For 24-trial condition blocks, returns a unique subset with exact
 * slot-position balance (12 M / 12 S at every one of the 8 positions). For
 * smaller blocks such as practice, falls back to the stateful
 * sample-without-replacement pool.
 */
export function drawBlockSequences({
  blockSize,
  label,
  prng = getSessionPRNG(),
  exactSlotBalance = blockSize === 24,
  maxAttempts = 50000,
} = {}) {
  if (typeof blockSize !== 'number' || blockSize < 1) {
    throw new Error(`drawBlockSequences: blockSize must be ≥ 1, got ${blockSize}`);
  }

  if (exactSlotBalance) {
    return drawExactlyBalancedUniqueBlock(blockSize, prng, maxAttempts);
  }

  const pool = createSequencePool(label ?? 'default', prng);
  const out = [];
  for (let i = 0; i < blockSize; i++) out.push(pool.next());
  return Object.freeze(out);
}

/**
 * Validate the run-length cap on an arbitrary sequence (exposed for tests
 * and any future external caller).
 */
export function isValidSequence(seq) {
  if (!Array.isArray(seq) || seq.length !== SEQUENCE_LENGTH) return false;
  let m = 0,
    s = 0;
  for (const c of seq) {
    if (c === 'M') m++;
    else if (c === 'S') s++;
    else return false;
  }
  if (m !== M_COUNT || s !== S_COUNT) return false;
  return withinRunLengthCap(seq, config.sequencing.within_trial_run_length_cap);
}
