/**
 * Headphone screen — Milne et al. (2021) antiphase variant.
 *
 * DEVIATION FROM DESIGN DOC §3.5: the pre-registration draft names the
 * Woods et al. (2017) Huggins-pitch test, which requires shipping a set of
 * pre-rendered noise stimuli. The Milne et al. (2021) antiphase test uses
 * the same logic (binaural cancellation that survives on headphones but
 * collapses on speakers) and is generatable in real time via Web Audio.
 * Same gate (≥5/6 correct), same false-positive rate in their published
 * comparison. This deviation is recorded in BUILD_LOG.md and must be
 * surfaced in the pre-registration update before lock.
 *
 * Each trial: three sequential 1-second 200 Hz tones, separated by 500 ms.
 * Two of the three are in-phase; one is antiphase ("Huggins-style" — same
 * frequency in both ears, one channel inverted). On headphones the
 * antiphase tone is clearly *quieter*; on speakers it largely cancels and
 * sounds nearly silent — but the cue we use is "which is quietest", which
 * works either way: speakers produce a *more* extreme quiet, headphones a
 * subtle one. Participant picks 1 / 2 / 3.
 */
import htmlButtonResponse from '@jspsych/plugin-html-button-response';
import callFunction from '@jspsych/plugin-call-function';
import { getSessionPRNG } from '../prng.js';
import { playInPhasePair, playAntiphasePair } from '../audio/dsp.js';
import { equalLoudnessGainDb70Phon } from '../audio/equal-loudness.js';
import { getAudioContext } from '../audio/context.js';
import { config } from '../config.js';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

const HP_TEST_FREQ_HZ = 200;
const HP_TONE_MS = 1000;
const HP_GAP_MS = 500;
const HP_PEAK = 0.18;
/* ISO 226:2003 70-phon equal-loudness compensation at 200 Hz (≈ +6 dB).
 * Applied identically to both ears so the in-phase / antiphase ratio that
 * carries the diagnostic cue is unchanged — we only raise the absolute
 * level of every tone to match what the experimental tone bank uses. With
 * peak 0.18 × 10^(6/20) ≈ 0.36 we stay well under the 0.95 clipping margin.
 * Without this, the screen would test audibility at ≈ 6 dB below the level
 * participants then encode at, so a borderline-audible 200 Hz tone could
 * pass the screen and still be too quiet during the task. */
const HP_GAIN_DB_70_PHON = equalLoudnessGainDb70Phon(HP_TEST_FREQ_HZ);

async function playOneTrial(targetIntervalIdx) {
  const ctx = getAudioContext();
  const start = ctx.currentTime + 0.2;
  const stepSec = (HP_TONE_MS + HP_GAP_MS) / 1000;
  for (let i = 0; i < 3; i++) {
    const when = start + i * stepSec;
    const opts = {
      durationMs: HP_TONE_MS,
      rampMs: 30,
      peak: HP_PEAK,
      gainDb: HP_GAIN_DB_70_PHON,
      when,
    };
    if (i === targetIntervalIdx) {
      playAntiphasePair(HP_TEST_FREQ_HZ, opts);
    } else {
      playInPhasePair(HP_TEST_FREQ_HZ, opts);
    }
  }
  const totalSec = 3 * stepSec + 0.2;
  await new Promise((r) => setTimeout(r, totalSec * 1000));
}

function trialNode(targetIntervalIdx, trialIndex) {
  const stepId = `headphone_screen_${trialIndex + 1}`;
  const node = {
    type: htmlButtonResponse,
    stimulus: `
      <h3>Headphone check (${trialIndex + 1} / ${config.headphone_screen.trials})</h3>
      <p>You will hear three tones. Click the one that sounds <strong>quietest</strong>.</p>
      <p style="opacity:0.7;">Listening…</p>
    `,
    choices: ['1', '2', '3'],
    button_html: (label) =>
      `<button class="jspsych-btn" disabled style="margin: 0 0.4rem; min-width: 4rem;">${label}</button>`,
    on_load: async () => {
      await playOneTrial(targetIntervalIdx);
      document
        .querySelectorAll('.jspsych-btn[disabled]')
        .forEach((b) => b.removeAttribute('disabled'));
    },
    on_finish: (data) => {
      data.target_interval = targetIntervalIdx;
      data.responded_interval = data.response;
      data.correct = data.response === targetIntervalIdx;
      /* Mirror the per-trial RT into `response_latency_ms` (rounded ms) so
       * the field name matches the rest of the data conventions. The raw
       * `rt` from htmlButtonResponse is RT from button-enable to click; we
       * round for stable CSV output. */
      data.response_latency_ms = Number.isFinite(data.rt) ? Math.round(data.rt) : null;
    },
    data: { phase: 'headphone_screen' },
  };
  registerHiddenNavStep(stepId, () => trialNode(targetIntervalIdx, trialIndex));
  return trackHiddenNavNode(node, stepId);
}

function readyNode(trialIndex) {
  const stepId = `headphone_screen_ready_${trialIndex + 1}`;
  const node = {
    type: htmlButtonResponse,
    stimulus: `<p>Get ready… click to play trial ${trialIndex + 1}.</p>`,
    choices: ['Play'],
    data: { phase: 'headphone_screen_ready' },
  };
  registerHiddenNavStep(stepId, () => readyNode(trialIndex));
  return trackHiddenNavNode(node, stepId);
}

export function headphoneScreenTimeline() {
  const prng = getSessionPRNG();
  const trials = [];
  /* Counterbalance target interval: 2 of each across 6 trials. */
  const targets = prng.shuffle([0, 0, 1, 1, 2, 2]);
  for (let i = 0; i < config.headphone_screen.trials; i++) {
    trials.push(readyNode(i));
    trials.push(trialNode(targets[i], i));
  }
  return trials;
}

/**
 * Returns { passed, correct, total }. Place after `headphoneScreenTimeline()`
 * and gate the next stage on `passed`.
 */
export function headphoneScreenGate() {
  return {
    type: callFunction,
    async: false,
    func: () => {
      const rows = window.jsPsych?.data?.get().filter({ phase: 'headphone_screen' }).values();
      const correct = rows.filter((r) => r.correct).length;
      const total = rows.length;
      const passed = correct >= config.headphone_screen.pass_threshold;
      return { passed, correct, total };
    },
    data: { phase: 'headphone_screen_gate' },
  };
}

/**
 * Friendly exit screen for participants who fail the headphone screen.
 */
export function headphoneFailExit() {
  return {
    timeline: [
      {
        type: htmlButtonResponse,
        stimulus: `
          <h2>Sorry — this study requires headphones</h2>
          <p>Based on the listening check, it looks like you may be using speakers
             or one of your headphones may be off. This study can only be completed
             with working stereo headphones.</p>
          <p>You may return the study on Prolific without penalty.</p>
        `,
        choices: ['Close'],
      },
    ],
    conditional_function: () => {
      const last = window.jsPsych?.data
        ?.get()
        .filter({ phase: 'headphone_screen_gate' })
        .last(1)
        .values()[0];
      const result = last?.value;
      return result ? !result.passed : false;
    },
  };
}
