/**
 * VVIQ — Marks's (1973) Vividness of Visual Imagery Questionnaire.
 *
 * 16 items grouped into 4 vignettes (4 items each). Each item is rated on
 * Marks's original 5-point clarity scale:
 *
 *   1 = Perfectly clear and as vivid as normal vision
 *   2 = Clear and reasonably vivid
 *   3 = Moderately clear and vivid
 *   4 = Vague and dim
 *   5 = No image at all; you only "know" that you are thinking of the object
 *
 * Scoring convention. Marks 1973 sums across the 16 items, range 16–80;
 * **lower scores = more vivid imagery**. Modern variants (VVIQ-2, VVIQ-RV)
 * sometimes reverse the scale so higher = more vivid. We store the **raw
 * Marks 1973 codes** in the data record (1 = most vivid, 5 = least), and the
 * `scoreVviq` helper exposes both totals so the analysis pipeline can pick
 * whichever convention it uses without re-coding.
 *
 * Decision log: PLAN §7 q7 recommended Marks 1973 verbatim. Wording below is
 * the published 1973 instrument (Marks, D. F. (1973). Visual imagery
 * differences in the recall of pictures. *British Journal of Psychology*,
 * 64(1), 17–24).
 */
import surveyHtmlForm from '@jspsych/plugin-survey-html-form';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

export const VVIQ_SCALE = Object.freeze([
  Object.freeze({ value: 1, label: 'Perfectly clear and as vivid as normal vision' }),
  Object.freeze({ value: 2, label: 'Clear and reasonably vivid' }),
  Object.freeze({ value: 3, label: 'Moderately clear and vivid' }),
  Object.freeze({ value: 4, label: 'Vague and dim' }),
  Object.freeze({
    value: 5,
    label: 'No image at all; you only "know" that you are thinking of the object',
  }),
]);

export const VVIQ_VIGNETTES = Object.freeze([
  Object.freeze({
    id: 'vviq_v1_relative',
    preamble:
      'Think of some relative or friend whom you frequently see (but who is not with you at present) and consider carefully the picture that comes before your mind’s eye.',
    items: Object.freeze([
      Object.freeze({
        id: 'vviq_q01',
        text: 'The exact contour of face, head, shoulders and body.',
      }),
      Object.freeze({
        id: 'vviq_q02',
        text: 'Characteristic poses of head, attitudes of body, etc.',
      }),
      Object.freeze({
        id: 'vviq_q03',
        text: 'The precise carriage, length of step, etc. in walking.',
      }),
      Object.freeze({
        id: 'vviq_q04',
        text: 'The different colours worn in some familiar clothes.',
      }),
    ]),
  }),
  Object.freeze({
    id: 'vviq_v2_sunrise',
    preamble:
      'Visualize the rising sun. Consider carefully the picture that comes before your mind’s eye.',
    items: Object.freeze([
      Object.freeze({
        id: 'vviq_q05',
        text: 'The sun is rising above the horizon into a hazy sky.',
      }),
      Object.freeze({
        id: 'vviq_q06',
        text: 'The sky clears and surrounds the sun with blueness.',
      }),
      Object.freeze({
        id: 'vviq_q07',
        text: 'Clouds. A storm blows up, with flashes of lightning.',
      }),
      Object.freeze({ id: 'vviq_q08', text: 'A rainbow appears.' }),
    ]),
  }),
  Object.freeze({
    id: 'vviq_v3_shop',
    preamble:
      'Think of the front of a shop which you often go to. Consider the picture that comes before your mind’s eye.',
    items: Object.freeze([
      Object.freeze({
        id: 'vviq_q09',
        text: 'The overall appearance of the shop from the opposite side of the road.',
      }),
      Object.freeze({
        id: 'vviq_q10',
        text: 'A window display including colours, shapes and details of individual items for sale.',
      }),
      Object.freeze({
        id: 'vviq_q11',
        text: 'You are near the entrance. The colour, shape and details of the door.',
      }),
      Object.freeze({
        id: 'vviq_q12',
        text: 'You enter the shop and go to the counter. The counter assistant serves you. Money changes hands.',
      }),
    ]),
  }),
  Object.freeze({
    id: 'vviq_v4_country',
    preamble:
      'Finally think of a country scene which involves trees, mountains, and a lake. Consider the picture that comes before your mind’s eye.',
    items: Object.freeze([
      Object.freeze({ id: 'vviq_q13', text: 'The contours of the landscape.' }),
      Object.freeze({ id: 'vviq_q14', text: 'The colour and shape of the trees.' }),
      Object.freeze({ id: 'vviq_q15', text: 'The colour and shape of the lake.' }),
      Object.freeze({
        id: 'vviq_q16',
        text: 'A strong wind blows on the trees and on the lake causing waves.',
      }),
    ]),
  }),
]);

const VVIQ_TOTAL_ITEMS = VVIQ_VIGNETTES.reduce((acc, v) => acc + v.items.length, 0);

if (VVIQ_TOTAL_ITEMS !== 16) {
  throw new Error(`VVIQ_VIGNETTES must contain exactly 16 items, got ${VVIQ_TOTAL_ITEMS}`);
}

/**
 * Render one vignette as a survey-html-form. Each item is a `<select>` so
 * keyboard-only navigation works (radio groups in HTML are clunky to label
 * when there are 5 options with long text). The select's `name=` attribute
 * uses the item id, which is also what we recover in `on_finish` below.
 *
 * @param {object} vignette  one entry from `VVIQ_VIGNETTES`
 * @returns {object}         jsPsych timeline node
 */
function vviqVignetteNode(vignette) {
  const itemRows = vignette.items
    .map((item) => {
      const optionsHtml = VVIQ_SCALE.map(
        (s) => `<option value="${s.value}">${s.value} — ${s.label}</option>`
      ).join('');
      return `
        <tr>
          <td style="padding: 0.5rem 0.75rem 0.5rem 0; vertical-align: top;">${item.text}</td>
          <td style="padding: 0.5rem 0; vertical-align: top;">
            <select name="${item.id}" required>
              <option value="">—</option>
              ${optionsHtml}
            </select>
          </td>
        </tr>`;
    })
    .join('');
  const stepId = vignette.id;
  const node = {
    type: surveyHtmlForm,
    preamble: `
      <h2>Imagery questionnaire (${vignette.id.replace('vviq_v', 'part ').split('_')[0]} of 4)</h2>
      <p style="max-width: 40rem; margin: 0.5rem auto; text-align: left;">
        ${vignette.preamble}
      </p>
      <p style="max-width: 40rem; margin: 0.5rem auto; text-align: left;">
        For each item below, rate the vividness of the image that comes to mind.
      </p>
    `,
    html: `
      <div style="max-width: 44rem; margin: 0 auto;">
        <table style="width: 100%; border-collapse: collapse; text-align: left;">
          ${itemRows}
        </table>
      </div>
    `,
    button_label: 'Continue',
    on_finish: (data) => {
      data.phase = 'vviq';
      data.vviq_vignette_id = vignette.id;
      data.vviq_responses = vignette.items.reduce((acc, item) => {
        const raw = data.response?.[item.id];
        acc[item.id] = raw === '' || raw === null || raw === undefined ? null : Number(raw);
        return acc;
      }, {});
    },
  };
  registerHiddenNavStep(stepId, () => vviqVignetteNode(vignette));
  return trackHiddenNavNode(node, stepId);
}

/**
 * Returns the four-vignette VVIQ timeline. Splice into the runner after
 * Main B and before the upload node.
 */
export function vviqTimeline() {
  return VVIQ_VIGNETTES.map(vviqVignetteNode);
}

/**
 * Score a set of VVIQ rows. Computes both Marks 1973 and the modern reversed
 * convention so downstream analyses can pick. Returns null for `markesTotal`
 * (and counterpart) if any of the 16 items is missing — the analyst should
 * decide how to handle partials, not us.
 *
 * @param {object[]} rows                jsPsych data rows (any phase)
 * @returns {{
 *   itemResponses: Record<string, number|null>,
 *   answered: number,
 *   total: number,
 *   marks1973Total: number|null,
 *   reversedTotal: number|null,
 *   complete: boolean
 * }}
 */
export function scoreVviq(rows) {
  const vviqRows = (rows ?? []).filter((r) => r?.phase === 'vviq');
  const itemResponses = {};
  for (const v of VVIQ_VIGNETTES) {
    for (const item of v.items) itemResponses[item.id] = null;
  }
  for (const row of vviqRows) {
    const responses = row.vviq_responses ?? {};
    for (const [k, v] of Object.entries(responses)) {
      if (k in itemResponses && Number.isFinite(v)) itemResponses[k] = v;
    }
  }
  const answered = Object.values(itemResponses).filter((v) => v !== null).length;
  const complete = answered === 16;
  const marks1973Total = complete
    ? Object.values(itemResponses).reduce((acc, v) => acc + v, 0)
    : null;
  /* Reversed convention: 1↔5, 2↔4, 3↔3. Equivalent to (6 − raw). */
  const reversedTotal = complete
    ? Object.values(itemResponses).reduce((acc, v) => acc + (6 - v), 0)
    : null;
  return {
    itemResponses,
    answered,
    total: 16,
    marks1973Total,
    reversedTotal,
    complete,
  };
}
