/**
 * Volume calibration.
 *
 * We can never know absolute SPL from a browser, but we can put the
 * participant's *system* volume in a sane range: we play a 1 kHz reference
 * tone in a loop and ask them to adjust system volume until it is "clearly
 * audible but not uncomfortable". After they confirm, the loop ends.
 *
 * Throughout the rest of the session, we drop *catch* tones at the bottom
 * of the audible range every block; if they're missed too often, we infer
 * the participant turned the volume down or removed headphones. That gate
 * lives in the main timeline (Step 8), not here.
 *
 * Teardown: when the participant clicks Continue, the next pulse must NOT
 * play. The earlier implementation set a `stop = true` flag from `on_finish`
 * and let the loop notice on its next iteration — but the iteration was
 * mid-`setTimeout`, so up to ~1 s of audio continued *after* the click and
 * sometimes overlapped the next trial's instructions. The current
 * implementation tracks the pending timer + the live oscillator/gain so it
 * can cancel both in `on_finish`, dropping audio within ~10 ms of the click.
 */
import htmlButtonResponse from '@jspsych/plugin-html-button-response';
import { getAudioContext } from '../audio/context.js';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

const REF_FREQ_HZ = 1000;
const REF_PEAK = 0.18;
const PULSE_MS = 600;
const GAP_MS = 400;
/* Brief gain-fade applied at teardown so cutting the loop doesn't click. */
const TEARDOWN_FADE_MS = 30;

export function volumeCalibrationTrial() {
  let stopped = false;
  let pendingTimerId = null;
  let pulseCount = 0;
  let loopStartedAtMs = null;
  /* Track only the most recently scheduled osc/gain. Earlier ones already
   * have their `osc.stop(when + ...)` set in absolute time and will free
   * themselves; the *current* pulse is the one that may still be ramping up
   * when the click arrives, so it's the one we explicitly silence. */
  let activeOsc = null;
  let activeGain = null;

  const stepId = 'volume_calibration';
  const node = {
    type: htmlButtonResponse,
    stimulus: `
      <h2>Set your volume</h2>
      <p style="max-width: 38rem; margin: 0 auto 1rem;">
        A 1 kHz reference tone is now looping. Use your computer's volume
        controls to make it <strong>clearly audible but not uncomfortable</strong>.
      </p>
      <p>Then click Continue.</p>
    `,
    choices: ['Continue'],
    on_load: async () => {
      const ctx = getAudioContext();
      const stepMs = PULSE_MS + GAP_MS;
      loopStartedAtMs = performance.now();
      while (!stopped) {
        const when = ctx.currentTime + 0.05;
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = REF_FREQ_HZ;
        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0, when);
        gain.gain.linearRampToValueAtTime(REF_PEAK, when + 0.02);
        gain.gain.setValueAtTime(REF_PEAK, when + PULSE_MS / 1000 - 0.02);
        gain.gain.linearRampToValueAtTime(0, when + PULSE_MS / 1000);
        osc.connect(gain).connect(ctx.destination);
        osc.start(when);
        osc.stop(when + PULSE_MS / 1000 + 0.05);
        activeOsc = osc;
        activeGain = gain;
        pulseCount += 1;
        /* Resolve the wait via an awaited Promise whose timer ID we hold —
         * `on_finish` clears it so the loop wakes up immediately and exits. */
        await new Promise((resolve) => {
          pendingTimerId = setTimeout(resolve, stepMs);
        });
        pendingTimerId = null;
      }
    },
    on_finish: (data) => {
      stopped = true;
      if (pendingTimerId !== null) {
        clearTimeout(pendingTimerId);
        pendingTimerId = null;
      }
      /* Fade the live pulse to zero rather than yanking it — abrupt stops
       * produce an audible click on most systems. */
      if (activeGain && activeOsc) {
        try {
          const ctx = getAudioContext();
          const now = ctx.currentTime;
          activeGain.gain.cancelScheduledValues(now);
          activeGain.gain.setValueAtTime(activeGain.gain.value, now);
          activeGain.gain.linearRampToValueAtTime(0, now + TEARDOWN_FADE_MS / 1000);
          activeOsc.stop(now + TEARDOWN_FADE_MS / 1000 + 0.01);
        } catch {
          /* Already stopped — nothing to do. */
        }
        activeGain = null;
        activeOsc = null;
      }
      data.confirmed = true;
      data.reference_freq_hz = REF_FREQ_HZ;
      data.pulse_count = pulseCount;
      data.calibration_duration_ms = loopStartedAtMs
        ? Math.round(performance.now() - loopStartedAtMs)
        : null;
    },
    data: { phase: 'volume_calibration' },
  };
  registerHiddenNavStep(stepId, volumeCalibrationTrial);
  return trackHiddenNavNode(node, stepId);
}

/**
 * Self-reported system volume in 0-100 percent. Browsers can't read OS
 * volume, but a self-report after the calibration loop closes correlates
 * well with delivered SPL on a fixed-output device (cf. Woods et al. 2017,
 * Milne et al. 2021 supplementary). Captured as `system_volume_pct` so
 * exclusion-rule filters can flag participants who set unusually low or
 * high settings.
 */
export function volumeSelfReportTrial() {
  const stepId = 'volume_self_report';
  const node = {
    type: htmlButtonResponse,
    stimulus: `
      <h2>One more thing — your volume setting</h2>
      <p style="max-width: 38rem; margin: 0 auto 1rem;">
        Roughly what is your <strong>system volume</strong> set to right now?
        Slide to estimate (0 = muted, 100 = maximum).
      </p>
      <div style="margin: 1.5rem auto; width: 24rem; max-width: 100%;">
        <input id="vol-pct-slider" type="range" min="0" max="100" value="50" style="width: 100%;" />
        <div style="display: flex; justify-content: space-between; font-size: 0.85rem; opacity: 0.7;">
          <span>0%</span><span id="vol-pct-readout">50%</span><span>100%</span>
        </div>
      </div>
    `,
    choices: ['Continue'],
    on_load: () => {
      const slider = document.getElementById('vol-pct-slider');
      const readout = document.getElementById('vol-pct-readout');
      const update = () => {
        readout.textContent = `${slider.value}%`;
      };
      slider.addEventListener('input', update);
    },
    on_finish: (data) => {
      const slider = document.getElementById('vol-pct-slider');
      const pct = slider ? parseInt(slider.value, 10) : null;
      data.system_volume_pct = Number.isFinite(pct) ? pct : null;
    },
    data: { phase: 'volume_self_report' },
  };
  registerHiddenNavStep(stepId, volumeSelfReportTrial);
  return trackHiddenNavNode(node, stepId);
}
